1	import { describe, it, expect } from "vitest";
2	import { nextGeneration } from "./game-of-life.js";
3	
4	describe("Game of Life - Next Generation", () => {
5	  it("should return no living cells for an empty grid", () => {
6	    expect(nextGeneration([])).toEqual([]);
7	  });
8	  it("should let a single living cell die from underpopulation", () => {
9	    expect(nextGeneration([[0, 0]])).toEqual([]);
10	  });
11	  it("should let two adjacent living cells die from underpopulation", () => {
12	    expect(
13	      nextGeneration([
14	        [0, 0],
15	        [1, 0],
16	      ]),
17	    ).toEqual([]);
18	  });
19	  it("should let a living cell with 2 live neighbors survive", () => {
20	    expect(
21	      nextGeneration([
22	        [0, 0],
23	        [1, 0],
24	        [2, 0],
25	      ]),
26	    ).toContainEqual([1, 0]);
27	  });
28	  it("should let a living cell with 3 live neighbors survive", () => {
29	    expect(
30	      nextGeneration([
31	        [0, 0],
32	        [1, 0],
33	        [0, 1],
34	        [1, 1],
35	      ]),
36	    ).toContainEqual([0, 0]);
37	  });
38	  it("should let a living cell with more than 3 live neighbors die from overpopulation", () => {
39	    expect(
40	      nextGeneration([
41	        [1, 1],
42	        [0, 1],
43	        [2, 1],
44	        [1, 0],
45	        [1, 2],
46	      ]),
47	    ).not.toContainEqual([1, 1]);
48	  });
49	  it("should bring a dead cell with exactly 3 live neighbors to life", () => {
50	    expect(
51	      nextGeneration([
52	        [0, 0],
53	        [1, 0],
54	        [0, 1],
55	      ]),
56	    ).toContainEqual([1, 1]);
57	  });
58	  it("should keep a block still life unchanged", () => {
59	    expect(
60	      nextGeneration([
61	        [0, 0],
62	        [1, 0],
63	        [0, 1],
64	        [1, 1],
65	      ]),
66	    ).toEqual([
67	      [0, 0],
68	      [1, 0],
69	      [0, 1],
70	      [1, 1],
71	    ]);
72	  });
73	  it("should oscillate a blinker from vertical to horizontal", () => {
74	    const next = nextGeneration([
75	      [1, 0],
76	      [1, 1],
77	      [1, 2],
78	    ]);
79	    expect(next).toHaveLength(3);
80	    expect(next).toEqual(
81	      expect.arrayContaining([
82	        [0, 1],
83	        [1, 1],
84	        [2, 1],
85	      ]),
86	    );
87	  });
88	  it("should oscillate a blinker from horizontal back to vertical", () => {
89	    const next = nextGeneration([
90	      [0, 1],
91	      [1, 1],
92	      [2, 1],
93	    ]);
94	    expect(next).toHaveLength(3);
95	    expect(next).toEqual(
96	      expect.arrayContaining([
97	        [1, 0],
98	        [1, 1],
99	        [1, 2],
100	      ]),
101	    );
102	  });
103	  it.todo("should handle cells at negative coordinates");
104	});
